#!/usr/bin/env python3
"""Rebuild episode bodies for S05 from the authoritative conversation branches."""
import subprocess
import re
import sys

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]


def git(*args):
    return subprocess.run(["git", "-C", REPO] + list(args),
                          capture_output=True, text=True, check=True).stdout


def collect(ep):
    beats = []
    for b in BRANCHES:
        out = git("log", "origin/friend/" + b, "--format=%H|%cI")
        for line in out.strip().splitlines():
            sha, ts = line.split("|")
            body = git("show", "-s", "--format=%B", sha)
            if "Friend-Message: 1" not in body:
                continue
            m = re.search(r"^Episode:\s*(\S+)\s*$", body, re.M)
            if not m or m.group(1) != ep:
                continue
            parts = body.split("\n")
            idx = next((i for i, l in enumerate(parts)
                        if l.startswith("Reply-To:")), None)
            if idx is None:
                continue
            j = idx + 1
            while j < len(parts) and parts[j].strip() == "":
                j += 1
            text = "\n".join(parts[j:]).rstrip("\n")
            speaker = re.search(r"^Speaker:\s*(.+)$", body, re.M).group(1).strip()
            beats.append({"sha": sha, "ts": ts, "branch": b,
                          "speaker": speaker, "text": text})
    beats.sort(key=lambda b: (b["ts"], b["sha"]))
    # Chandler's 02:20:17 pair shares a timestamp; his own notes on
    # friend/chandler give the spoken order and the reply-to threads agree.
    i_ba = next(i for i, b in enumerate(beats)
                if b["sha"].startswith("ba1a9ae2"))
    i_aa = next(i for i, b in enumerate(beats)
                if b["sha"].startswith("aa144901"))
    if i_ba > i_aa:
        beats[i_ba], beats[i_aa] = beats[i_aa], beats[i_ba]
    blocks = ["**%s** (%s)\n\nSource: friend/%s @ %s\n\n%s\n"
              % (b["speaker"], b["ts"], b["branch"], b["sha"], b["text"])
              for b in beats]
    return "\n".join(blocks) + "\n", len(beats)


if __name__ == "__main__":
    ep = sys.argv[1]
    body, n = collect(ep)
    sys.stdout.write(body)
    sys.stderr.write("%s beats: %d\n" % (ep, n))

#!/usr/bin/env python3
"""Check whether regenerating an episode file from the branches preserves it."""
import subprocess
import re
import sys

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
PAT = (r"\*\*(\w+)\*\* \(([^)]+)\)\n\nSource: friend/(\w+) @ "
       r"([0-9a-f]{40})\n\n(.*?)\n\n(?=\*\*|<!--|\Z)")


def git(*a):
    return subprocess.run(["git", "-C", REPO] + list(a),
                          capture_output=True, text=True, check=True).stdout


def collect(ep):
    beats = {}
    for b in BRANCHES:
        for line in git("log", "origin/friend/" + b,
                        "--format=%H|%cI").strip().splitlines():
            sha, ts = line.split("|")
            body = git("show", "-s", "--format=%B", sha)
            if "Friend-Message: 1" not in body:
                continue
            m = re.search(r"^Episode:\s*(\S+)\s*$", body, re.M)
            if not m or m.group(1) != ep:
                continue
            parts = body.split("\n")
            idx = next((i for i, l in enumerate(parts)
                        if l.startswith("Reply-To:")), None)
            if idx is None:
                continue
            j = idx + 1
            while j < len(parts) and parts[j].strip() == "":
                j += 1
            beats[sha] = {
                "ts": ts, "branch": b,
                "speaker": re.search(r"^Speaker:\s*(.+)$", body,
                                     re.M).group(1).strip(),
                "text": "\n".join(parts[j:]).rstrip("\n"),
            }
    return beats


def check(path):
    ep = path.replace(".md", "")
    beats = collect(ep)
    text = git("show", "origin/main:" + path)
    entries = re.findall(PAT, text, re.S)
    file_order = [e[3] for e in entries]
    ordered = sorted(beats.values(), key=lambda b: (b["ts"], b["sha"]))
    regen_order = [s for s in sorted(beats,
                                     key=lambda s: (beats[s]["ts"], s))]
    print(path, "file:", len(file_order), "branch:", len(regen_order))
    missing = [s for s in regen_order if s not in file_order]
    print("  missing:", missing)
    # order check on the intersection
    inter_regen = [s for s in regen_order if s in file_order]
    inter_file = [s for s in file_order if s in regen_order]
    print("  order preserved on shared:", inter_regen == inter_file)
    if inter_regen != inter_file:
        for i, (a, b) in enumerate(zip(inter_regen, inter_file)):
            if a != b:
                print("   first divergence at", i, a, b)
                break
    # text check
    for e in entries:
        b = beats.get(e[3])
        if b is None:
            print("  file entry not on branch:", e[3])
        elif b["text"] != e[4] or b["speaker"] != e[0]:
            print("  TEXT DIFF", e[3])


for p in sys.argv[1:]:
    check(p)

